-- ************************************** Used
CREATE TABLE Used
(
 employee_number numeric(5) NOT NULL,
 material_number numeric(5) NOT NULL,
 project_number  numeric(5) NOT NULL,
 task_name       char(30) NOT NULL,

 CONSTRAINT PK_Used PRIMARY KEY ( employee_number, material_number ),
 CONSTRAINT FK_3 FOREIGN KEY ( project_number, task_name, employee_number ) REFERENCES Participate ( project_number, task_name, employee_number ),
 CONSTRAINT FK_Used_Employee FOREIGN KEY ( employee_number ) REFERENCES Employee ( employee_number ),
 CONSTRAINT FK_Used_Material FOREIGN KEY ( material_number ) REFERENCES Material ( material_number )
);
